`,e.jsx(n.h5,{id:"1-resource-lifetime-and-the-actual-settlement-boundary",children:"1. Resource lifetime and the actual settlement boundary"}),`
`,e.jsxs(n.p,{children:["The extension factory may load without a session. Long-lived processes/watchers belong in session_start or their owning command/tool; cleanup belongs in idempotent session_shutdown. Reload and session replacement invalidate old runtime/context objects. A later withSession callback receives the replacement context. agent_end ends a low-level run; retries, compaction, or queued work can follow. agent_before_settle is the actionable final boundary, while agent_settled is notification-only. ",e.jsx(n.a,{href:"https://github.com/earendil-works/pi/blob/482c1381a00d8d00bc81697e4a980c593db6803e/packages/coding-agent/docs/extensions.md#L54-L150",children:"Lifecycle documentation"}),", ",e.jsx(n.a,{href:"https://github.com/earendil-works/pi/blob/482c1381a00d8d00bc81697e4a980c593db6803e/packages/coding-agent/docs/extensions.md#L307-L332",children:"replacement context"}),", ",e.jsx(n.a,{href:"https://github.com/earendil-works/pi/blob/482c1381a00d8d00bc81697e4a980c593db6803e/packages/coding-agent/src/core/agent-session.ts#L3690-L3730",children:"reload implementation"})]}),`
`,e.jsxs(n.p,{children:[e.jsx(n.strong,{children:"Adapter implication, proposed:"})," an engine connection, capture lease, and evidence recorder need explicit ownership and shutdown/rebind behavior. Do not finalize an evaluation at the first agent_end or continue using a pre-reload engine handle."]}),`
`,e.jsx(n.h5,{id:"2-cancellation-is-cooperative-nested-signal-overrides-matter",children:"2. Cancellation is cooperative; nested signal overrides matter"}),`
`,e.jsxs(n.p,{children:["The core checks cancellation before execution, then awaits tool.execute with the supplied AbortSignal. This path has no forced termination or rollback wrapper. A tool that ignores its signal can continue and return normally. Nested executeTool defaults to its parent's signal, but an explicitly supplied signal ",e.jsx(n.strong,{children:"replaces"})," that default; this call site does not combine signals. ",e.jsx(n.a,{href:"https://github.com/earendil-works/pi/blob/482c1381a00d8d00bc81697e4a980c593db6803e/packages/agent/src/agent-loop.ts#L708-L779",children:"Execution"}),", ",e.jsx(n.a,{href:"https://github.com/earendil-works/pi/blob/482c1381a00d8d00bc81697e4a980c593db6803e/packages/agent/src/agent-loop.ts#L821-L859",children:"awaited execution and error conversion"}),", ",e.jsx(n.a,{href:"https://github.com/earendil-works/pi/blob/482c1381a00d8d00bc81697e4a980c593db6803e/packages/coding-agent/src/core/extensions/runner.ts#L968-L994",children:"nested signal selection"})]}),`
`,e.jsxs(n.p,{children:["RPC abort waits for idle but does not clear queued messages; clear_queue followed by abort is documented for Esc-like behavior. ",e.jsx(n.a,{href:"https://github.com/earendil-works/pi/blob/482c1381a00d8d00bc81697e4a980c593db6803e/packages/coding-agent/docs/rpc-commands.md#L94-L128",children:"RPC contract"})]}),`
`,e.jsxs(n.p,{children:[e.jsx(n.strong,{children:"Adapter implication, proposed:"})," distinguish cancel-requested, engine-acknowledged-stop, completed-after-cancel, and outcome-unknown. Reconcile job IDs and authoritative engine state before retrying a mutation. A timeout signal must preserve intended parent-cancellation semantics explicitly."]}),`
`,e.jsx(n.h5,{id:"3-original-image-persisted-result-and-request-context-differ",children:"3. Original image, persisted result, and request context differ"}),`
`,e.jsxs(n.p,{children:["_afterToolCall runs extension tool_result handlers and then normalizes their image content with the current model's resize profile and image settings. normalizeToolResultImages invokes processImage, can replace bytes/MIME type and add hints, but preserves the original block when processImage returns ok:false; this wrapper does not catch arbitrary thrown exceptions. Disabling resizing still permits unsupported-format conversion. Thus the persisted tool-result image need not equal the original screenshot, and normalization failure does not certify provider compatibility. ",e.jsx(n.a,{href:"https://github.com/earendil-works/pi/blob/482c1381a00d8d00bc81697e4a980c593db6803e/packages/coding-agent/src/core/agent-session.ts#L684-L726",children:"Hook ordering"}),", ",e.jsx(n.a,{href:"https://github.com/earendil-works/pi/blob/482c1381a00d8d00bc81697e4a980c593db6803e/packages/coding-agent/src/utils/tool-result-images.ts",children:"normalization"}),", ",e.jsx(n.a,{href:"https://github.com/earendil-works/pi/blob/482c1381a00d8d00bc81697e4a980c593db6803e/packages/coding-agent/src/utils/image-process.ts",children:"conversion/resize"})]}),`
`,e.jsxs(n.p,{children:["Request-time context processing starts from a structured clone; context handlers receive conversation messages while system state is restored, followed by context_with_system on the full transcript. Separately, a tool_result handler replacing content without structuredContent drops the prior structured result. ",e.jsx(n.a,{href:"https://github.com/earendil-works/pi/blob/482c1381a00d8d00bc81697e4a980c593db6803e/packages/coding-agent/src/core/extensions/runner.ts#L1300-L1355",children:"Context composition"}),", ",e.jsx(n.a,{href:"https://github.com/earendil-works/pi/blob/482c1381a00d8d00bc81697e4a980c593db6803e/packages/coding-agent/src/core/extensions/runner.ts#L1189-L1247",children:"result composition"})]}),`
`,e.jsxs(n.p,{children:[e.jsx(n.strong,{children:"Adapter implication, proposed:"})," record original artifact hash/dimensions, stored derivative identity, selection transformations, and request-evidence manifest separately. Context compression must not silently destroy the structured manifest needed by nested orchestration. Final provider preprocessing remains an additional boundary, not verified here."]}),`
`,e.jsx(n.h5,{id:"4-resuming-a-conversation-does-not-establish-engine-job-recovery",children:"4. Resuming a conversation does not establish engine-job recovery"}),`
`,e.jsxs(n.p,{children:["Session context follows the active branch and latest compaction; older summarized entries are omitted from active context but remain in the session file. The default summary serializer extracts text, not image pixels, and truncates tool-result text longer than 2,000 characters to that prefix plus a marker; shorter text remains unchanged. An image retained in the kept tail differs from an image whose entry was summarized away. ",e.jsx(n.a,{href:"https://github.com/earendil-works/pi/blob/482c1381a00d8d00bc81697e4a980c593db6803e/packages/coding-agent/src/core/session-manager.ts#L469-L573",children:"Session projection"}),", ",e.jsx(n.a,{href:"https://github.com/earendil-works/pi/blob/482c1381a00d8d00bc81697e4a980c593db6803e/packages/coding-agent/src/core/compaction/utils.ts#L90-L155",children:"summary serializer"}),", ",e.jsx(n.a,{href:"https://github.com/earendil-works/pi/blob/482c1381a00d8d00bc81697e4a980c593db6803e/packages/coding-agent/src/core/compaction/compaction.ts#L679-L735",children:"default summary request"}),", ",e.jsx(n.a,{href:"https://github.com/earendil-works/pi/blob/482c1381a00d8d00bc81697e4a980c593db6803e/packages/coding-agent/docs/sessions.md",children:"session semantics"})]}),`
`,e.jsxs(n.p,{children:["Branch-aware state should reconstruct from getBranch; appendEntry stores non-context data, while sendMessage adds model context. This is not evidence of durable continuation of an interrupted JavaScript execution, engine process, or remote job. ",e.jsx(n.a,{href:"https://github.com/earendil-works/pi/blob/482c1381a00d8d00bc81697e4a980c593db6803e/packages/coding-agent/docs/extensions.md#L320-L332",children:"State contract"})]}),`
`,e.jsxs(n.p,{children:[e.jsx(n.strong,{children:"Adapter implication, proposed:"})," persist artifact/job identities and authoritative completion status externally; revalidate them on resume. Branch switching must not mix accepted assets or completion records from alternative histories."]}),`
